package org.apache.commons.math.optimization.general;

import java.io.*;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.MultivariateFunction;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.fitting.WeightedLeastSquaresOptimizer;
import org.apache.commons.math.fitting.WeightedLeastSquaresProblem;
import org.apache.commons.math.fitting.WeightedObservedPoint;
import org.apache.commons.math.fitting.WeightedObservedPoints;
import org.apache.commons.math.optimization.InitialGuess;
import org.apache.commons.math.optimization.MaxEval;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;
import org.apache.commons.math.optimization.nonlinear.scalar.GoalType;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.NotImplementedException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertThrows;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for LevenbergMarquardtOptimizer.doOptimize().
 * Since doOptimize is protected, we use a subclass or reflection to trigger it.
 */
public class LevenbergMarquardtOptimizer_doOptimize_TriageGen2Test {

    private TestableLevenbergMarquardtOptimizer optimizer;

    // Subclass to expose the protected doOptimize method
    private static class TestableLevenbergMarquardtOptimizer extends LevenbergMarquardtOptimizer {
        public VectorialPointValuePair doOptimizePublic() throws Exception {
            return doOptimize();
        }

        // Helper to inject a mock checker via reflection if needed, 
        // though the original code uses a 'checker' field.
        public void setChecker(Object checker) throws Exception {
            Field field = LevenbergMarquardtOptimizer.class.getDeclaredField("checker");
            field.setAccessible(true);
            field.set(this, checker);
        }
    }

    @Before
    public void setUp() {
        optimizer = new TestableLevenbergMarquardtOptimizer();
    }

    /**
     * Test 1: Standard convergence scenario.
     * Fits a simple linear model y = ax.
     */
    @Test
    public void testDoOptimize_StandardConvergence() throws Exception {
        WeightedObservedPoints points = new WeightedObservedPoints();
        points.add(1.0, 2.0);
        points.add(2.0, 4.0);
        points.add(3.0, 6.0);

        MultivariateFunction model = params -> params[0] * 1.0; // y = a * x

        WeightedLeastSquaresProblem problem = new WeightedLeastSquaresProblem(
                new LevenbergMarquardtOptimizer(),
                new org.apache.commons.math3.fitting.ModelFunction<double[], double[]>() {
                    @Override
                    public double[] value(double[] point) {
                        return new double[]{point[0]};
                    }
                },
                points.toList().toArray(new WeightedObservedPoint[0]),
                new InitialGuess(new double[]{1.0}),
                new MaxEval(100)
        );

        // We need to mock the problem components because the optimizer uses internal state
        // In Commons Math, the optimizer is passed to the problem.
        // For a real integration test, we use the problem.optimize() which calls doOptimize().

        VectorialPointValuePair result = problem.optimize();

        assertNotNull(result);
        assertEquals(2.0, result.getPoint()[0], 1e-5);
    }

    /**
     * Test 2: Test convergence via Orthogonality Tolerance.
     * We force a scenario where the gradient is zero.
     */
    @Test
    public void testDoOptimize_OrthoToleranceConvergence() throws Exception {
        optimizer.setOrthoTolerance(1e-3);

        // Mocking the internal state of the optimizer is difficult because doOptimize 
        // relies heavily on updateResidualsAndCost() and updateJacobian().
        // We simulate a zero-gradient scenario using a constant function.

        WeightedObservedPoints points = new WeightedObservedPoints();
        points.add(1.0, 5.0);
        points.add(2.0, 5.0);

        MultivariateFunction model = params -> 5.0; // Constant function, gradient is 0

        WeightedLeastSquaresProblem problem = new WeightedLeastSquaresProblem(
                optimizer,
                new org.apache.commons.math3.fitting.ModelFunction<double[], double[]>() {
                    @Override
                    public double[] value(double[] point) {
                        return new double[]{5.0};
                    }
                },
                points.toList().toArray(new WeightedObservedPoint[0]),
                new InitialGuess(new double[]{1.0}),
                new MaxEval(10)
        );

        VectorialPointValuePair result = problem.optimize();
        assertNotNull(result);
    }

    /**
     * Test 3: Test Exception - Too Small Cost Relative Tolerance.
     * Triggered when actRed and preRed are extremely small.
     */
    @Test
    public void testDoOptimize_TooSmallCostRelativeTolerance() throws Exception {
        // We use a very small tolerance to trigger the machine epsilon check
        optimizer.setCostRelativeTolerance(1e-20);

        WeightedObservedPoints points = new WeightedObservedPoints();
        points.add(1.0, 1.0);

        MultivariateFunction model = params -> 1.0;

        WeightedLeastSquaresProblem problem = new WeightedLeastSquaresProblem(
                optimizer,
                new org.apache.commons.math3.fitting.ModelFunction<double[], double[]>() {
                    @Override
                    public double[] value(double[] point) {
                        return new double[]{1.0};
                    }
                },
                points.toList().toArray(new WeightedObservedPoint[0]),
                new InitialGuess(new double[]{1.0}),
                new MaxEval(10)
        );

        // Depending on implementation, this might throw OptimizationException
        // or just converge. If it hits the 2.2204e-16 threshold, it throws.
        try {
            problem.optimize();
        } catch (Exception e) {
            // If it's an OptimizationException, it's a successful test of the branch
            assertNotNull(e.getMessage());
        }
    }

    /**
     * Test 4: Test Convergence via Checker.
     * Uses a mock checker to simulate convergence.
     */
    public interface ConvergenceChecker {
        boolean converged(int iterations, VectorialPointValuePair previous, VectorialPointValuePair current);
    }

    @Test
    public void testDoOptimize_WithChecker() throws Exception {
        ConvergenceChecker mockChecker = mock(ConvergenceChecker.class);
        when(mockChecker.converged(org.mockito.ArgumentMatchers.anyInt(), 
                                   org.mockito.ArgumentMatchers.any(), 
                                   org.mockito.ArgumentMatchers.any()))
            .thenReturn(true);

        optimizer.setChecker(mockChecker);

        WeightedObservedPoints points = new WeightedObservedPoints();
        points.add(1.0, 2.0);

        WeightedLeastSquaresProblem problem = new WeightedLeastSquaresProblem(
                optimizer,
                new org.apache.commons.math3.fitting.ModelFunction<double[], double[]>() {
                    @Override
                    public double[] value(double[] point) {
                        return new double[]{point[0]};
                    }
                },
                points.toList().toArray(new WeightedObservedPoint[0]),
                new InitialGuess(new double[]{1.0}),
                new MaxEval(10)
        );

        VectorialPointValuePair result = problem.optimize();
        assertNotNull(result);
    }

    /**
     * Test 5: Parameter Relative Tolerance convergence.
     */
    @Test
    public void testDoOptimize_ParRelativeTolerance() throws Exception {
        optimizer.setParRelativeTolerance(1e-5);

        WeightedObservedPoints points = new WeightedObservedPoints();
        points.add(1.0, 2.0);

        WeightedLeastSquaresProblem problem = new WeightedLeastSquaresProblem(
                optimizer,
                new org.apache.commons.math3.fitting.ModelFunction<double[], double[]>() {
                    @Override
                    public double[] value(double[] point) {
                        return new double[]{point[0]};
                    }
                },
                points.toList().toArray(new WeightedObservedPoint[0]),
                new InitialGuess(new double[]{1.0}),
                new MaxEval(10)
        );

        VectorialPointValuePair result = problem.optimize();
        assertNotNull(result);
    }

    /**
     * Test 6: Test the "Failed Iteration" branch (ratio < 1e-4).
     * This is achieved by providing a step that increases the cost.
     */
    @Test
    public void testDoOptimize_FailedIteration() throws Exception {
        // We simulate a model where moving in the direction of the gradient increases cost
        // This is hard to do with standard Math3 classes without complex setup, 
        // but we can use a model that is non-convex or has very high curvature.

        WeightedObservedPoints points = new WeightedObservedPoints();
        points.add(1.0, 10.0);
        points.add(1.1, 10.0);

        // A function where the derivative points "away" from the minimum
        // or creates a very bad ratio.
        WeightedLeastSquaresProblem problem = new WeightedLeastSquaresProblem(
                optimizer,
                new org.apache.commons.math3.fitting.ModelFunction<double[], double[]>() {
                    @Override
                    public double[] value(double[] point) {
                        // y = 1/x (gradient is negative, but if we start at small x, 
                        // the step might be huge and increase cost)
                        return new double[]{1.0 / point[0]};
                    }
                },
                points.toList().toArray(new WeightedObservedPoint[0]),
                new InitialGuess(new double[]{0.0001}),
                new MaxEval(5)
        );

        VectorialPointValuePair result = problem.optimize();
        assertNotNull(result);
    }
}
